SELECT IFNULL(SUM(CAST(cost_fee AS SIGNED)), 0)
FROM orders_normal_orders_items
WHERE company_id = #{companyId}
  AND order_id = #{orderId}
  AND supplier_id >= 1

SELECT IFNULL(SUM(COALESCE(num, 0)), 0)
FROM aftersales_detail
WHERE company_id = #{companyId}
  AND order_id = #{orderId}

SELECT order_id AS orderId, IFNULL(SUM(num), 0) AS num
FROM orders_normal_orders_items
WHERE company_id = #{companyId}
  AND supplier_id = #{operatorId}
  AND order_id IN

	#{oid}

GROUP BY order_id
